":"Service","name":"Homeowner Claim Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/home-insurance-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Condo, HOA & Commercial Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/condo-hoa-commercial-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/roof-hail-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Windstorm & Tornado Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/windstorm-tornado-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fallen Tree Damage Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/tree-impact-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Rain Intrusion Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/water-rain-intrusion-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/house-fire-smoke-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wildfire & Ash Claim Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/wildfire-ash-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Snow, Ice Dam & Freeze Appraisal","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/snow-ice-freeze-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Carrier Estimate Review","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Neutral Umpire Services","url":"https://washingtoninsuranceappraiser.com/insurance-appraisal-services/neutral-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Windstorm damage","Wildfire claims","Xactimate estimating"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://washingtoninsuranceappraiser.com/#website","url":"https://washingtoninsuranceappraiser.com/","name":"Washington Insurance Appraiser","publisher":{"@id":"https://washingtoninsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#webpage","url":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/","name":"Insurance Claim Glossary | ACV, RCV, Umpire & More","description":"A searchable glossary of 40+ property claim terms, from actual cash value and holdback to IFCA, umpire and Xactimate, in plain English.","inLanguage":"en-US","isPartOf":{"@id":"https://washingtoninsuranceappraiser.com/#website"},"about":{"@id":"https://washingtoninsuranceappraiser.com/#business"},"publisher":{"@id":"https://washingtoninsuranceappraiser.com/#business"},"dateModified":"2026-11-14","breadcrumb":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#breadcrumb"},"primaryImageOfPage":{"@type":"ImageObject","@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#primaryimage","url":"https://washingtoninsuranceappraiser.com/assets/img/photos/paperwork-review.webp","width":1200,"height":800,"caption":"Person at a desk holding a pen over paperwork"},"mainEntity":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://washingtoninsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim glossary","item":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/"}],"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Property insurance claim appraisal glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Many policies pay ACV first, then pay the depreciation once repairs are made.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for the extra cost of living elsewhere while a home is being repaired after a covered loss. Often called Coverage D or loss of use.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of covered damage. This is what an appraisal panel decides.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision of an appraisal panel setting the amount of loss, signed by at least two of the three panel members.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition that lets either party demand appraisal when they disagree on the amount of loss.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Atmospheric river","description":"A long, narrow band of moisture that brings heavy, sustained rain. Western Washington sees several each winter.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Bomb cyclone","description":"A storm whose pressure drops very quickly, producing strong winds. The November 2024 storm that hit Puget Sound was one.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Code upgrade","description":"Work needed to bring repairs up to current building codes. Usually paid under ordinance or law coverage.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Collapse","description":"A sudden falling down of a building or part of it. Policies define it narrowly and cover it only in certain situations.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Contents","description":"Personal belongings, covered under Coverage C in most homeowner policies.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage for the house itself and attached structures.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage for detached garages, sheds, fences and similar.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Debris removal","description":"Coverage for removing damaged property and debris after a covered loss, often with a separate limit.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of your policy showing coverages, limits, deductibles and the policy period.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value because of age, wear or obsolescence. Subtracted from replacement cost to get ACV.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Earthquake deductible","description":"A separate deductible for earthquake coverage, usually a percentage of the dwelling limit.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Extended replacement cost","description":"An endorsement that pays above the dwelling limit, such as 25% or 50% more, if rebuilding costs exceed it.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Flood exclusion","description":"The standard policy exclusion for damage from surface water, rising rivers and similar. Flood needs separate coverage.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"HO-3","description":"The most common homeowner policy form, covering the dwelling on an open-perils basis and contents on a named-perils basis.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"HO-6","description":"A policy for condominium unit owners covering unit improvements, contents and liability.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Holdback","description":"Recoverable depreciation the insurer withholds until repairs are completed.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the roof edge that traps melting snow, which can back up under shingles and leak inside.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"IFCA","description":"Washington’s Insurance Fair Conduct Act, which provides legal remedies for unreasonable denial of coverage or benefits.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Independent appraiser","description":"An appraiser with no financial interest in the outcome or the repair contract, as most appraisal clauses require.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate, such as removing and replacing a square of shingles.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Master policy","description":"The insurance policy a condominium or homeowners association buys to cover common areas and building elements.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Matching","description":"Whether replacement materials must match undamaged ones so the repair looks uniform. A common source of dispute.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Mitigation","description":"Steps taken to prevent further damage after a loss, such as tarping or water extraction. Policies require it.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"OIC","description":"The Washington Office of the Insurance Commissioner, the state regulator of insurance companies and agents.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for extra costs caused by building codes or laws when repairing or rebuilding.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charge for coordinating multiple trades, often 10% overhead plus 10% profit.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which the insurer may request within a set time.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation you can collect after completing repairs under a replacement cost policy.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deducting depreciation.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Scope of loss","description":"The list of everything that is damaged and how it must be repaired. The foundation of any estimate.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Steep charge","description":"Extra labor cost for working on roofs with a steep pitch, often 7/12 and above.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy clause setting how long you have to file a lawsuit. Washington law sets a one-year minimum.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Supplement","description":"A request to the insurer to add items or money to an estimate, supported by documentation.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Surplus lines","description":"Insurance from carriers not licensed in the state but allowed to write coverage that the standard market won’t.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers can’t agree on.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software used by most insurers and contractors, with regional price lists.","inDefinedTermSet":{"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}}],"@id":"https://washingtoninsuranceappraiser.com/claim-appraisal-glossary/#definedtermset"}]}</script>
</head>
